@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Rye&display=swap');
:root{--ink:#f8edda;--muted:#cbbca5;--rust:#a9502b;--gold:#eab45b;--dark:#211c18;--glass:rgba(34,28,23,.78);--line:rgba(255,244,221,.16)}
*{box-sizing:border-box}html,body,#game{width:100%;height:100%;margin:0;overflow:hidden}body{font-family:'DM Sans',sans-serif;background:#c98759;color:var(--ink)}button{font:inherit;color:inherit;cursor:pointer}#game{position:relative;isolation:isolate}#world{position:absolute;inset:0;width:100%;height:100%;z-index:-3;display:block}.vignette{position:absolute;inset:0;z-index:-2;pointer-events:none;background:linear-gradient(180deg,rgba(39,24,16,.22),transparent 28%,transparent 60%,rgba(38,23,15,.36)),linear-gradient(90deg,rgba(31,23,18,.2),transparent 38%,transparent 70%,rgba(31,23,18,.1))}.glass{background:var(--glass);border:1px solid rgba(255,240,214,.2);box-shadow:0 12px 35px rgba(34,18,8,.24);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px)}
.topbar{height:83px;position:absolute;top:0;left:0;right:0;display:flex;align-items:center;justify-content:space-between;padding:0 34px;border-bottom:1px solid rgba(255,248,231,.15);background:linear-gradient(180deg,rgba(37,25,19,.35),transparent)}.brand{display:flex;align-items:center;gap:12px;color:#fff4de;text-decoration:none;font-weight:800;font-size:18px;letter-spacing:1px;line-height:1}.brand i{font-family:'Rye',serif;color:#eab45b;font-style:normal}.brand small{display:block;color:#e8c89f;font-size:8px;letter-spacing:2px;margin-top:6px;font-weight:700}.brand-mark{display:grid;place-items:center;width:39px;height:39px;border-radius:12px;background:#a94e2c;color:#ffe1a3;font-size:23px;box-shadow:inset 0 0 0 1px #e6aa5b}.top-right{display:flex;align-items:center;gap:12px}.weather{display:flex;align-items:center;gap:10px;padding-right:19px;border-right:1px solid var(--line);margin-right:3px}.weather .sun-icon{font-size:23px;color:#ffd278}.weather b,.weather small{display:block}.weather b{font-size:9px;letter-spacing:1.2px}.weather small{font-size:11px;color:#e4cbb0;margin-top:3px}.sound-button,.icon-button{width:37px;height:37px;border:1px solid rgba(255,245,223,.3);border-radius:50%;background:rgba(27,22,18,.3);font-size:16px}.sound-button{color:#ffd47d}.sound-button.active{background:#e2a954;color:#2c2118}.icon-button{font-weight:700;font-size:14px}
.left-panel{position:absolute;top:108px;left:30px;width:272px;padding:20px 20px 15px;border-radius:16px}.eyebrow{font-size:9px;letter-spacing:1.6px;font-weight:800;color:#e8be7d}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a4d777;margin:0 6px 1px 0;box-shadow:0 0 8px #a4d777}.horse-heading{display:flex;justify-content:space-between;align-items:center;margin-top:12px}.horse-heading h1{font-family:'Rye',serif;font-size:27px;font-weight:400;margin:0;color:#fff3dc;letter-spacing:.3px}.horse-heading p{margin:5px 0 0;color:#d3b99a;font-size:9px;letter-spacing:1.1px;font-weight:700}.horse-heading p span{color:#e7ad56;padding:0 4px}.level-badge{border:1px solid rgba(232,180,91,.44);border-radius:9px;color:#e9bd73;font-size:8px;letter-spacing:1px;padding:6px 8px}.level-badge b{font-size:12px;color:#fff1cf;margin-left:3px}.horse-art{height:105px;position:relative;display:grid;place-items:center;overflow:hidden;margin:12px -5px 10px;border-radius:12px;background:radial-gradient(ellipse at 50% 85%,rgba(222,152,69,.35),transparent 65%),linear-gradient(140deg,rgba(255,255,255,.07),rgba(255,255,255,0))}.horse-glow{position:absolute;width:110px;height:18px;background:rgba(231,168,79,.24);filter:blur(16px);bottom:14px}.horse-emoji{position:relative;font-size:76px;filter:drop-shadow(0 9px 5px rgba(28,16,8,.5));transform:scaleX(-1);line-height:1}.horse-caption{position:absolute;bottom:7px;right:8px;font-size:7px;letter-spacing:1px;color:#dfc29e}.stat-list{display:grid;gap:11px}.stat-row{display:flex;gap:9px;align-items:center}.stat-row>span{width:17px;font-size:13px;text-align:center}.stat-info{flex:1}.stat-info>div:first-child{display:flex;justify-content:space-between;font-size:10px;margin-bottom:5px}.stat-info b{font-weight:600}.stat-info span{color:#dfc59f}.meter,.quest-line{height:5px;border-radius:5px;background:rgba(255,255,255,.14);overflow:hidden}.meter i,.quest-line i{height:100%;display:block;background:linear-gradient(90deg,#d98c4f,#f4c778);border-radius:inherit;transition:width .5s}.meter.stamina i{background:linear-gradient(90deg,#6aaf77,#b8d784)}.meter.spirit i{background:linear-gradient(90deg,#a77ed0,#d6a5dc)}.horse-switch{display:flex;justify-content:space-between;align-items:center;margin-top:13px;padding-top:10px;border-top:1px solid var(--line)}.horse-switch button{border:0;background:none;color:#e5c595;font-size:24px;padding:0 5px;line-height:1}.horse-switch span{display:flex;gap:5px}.horse-switch i{width:5px;height:5px;border-radius:50%;background:#7f7060}.horse-switch i.active{background:#edb75d;box-shadow:0 0 5px #edb75d}
.quest-card{position:absolute;top:108px;right:30px;width:264px;padding:17px;border-radius:16px;transition:transform .3s,opacity .3s}.quest-card.collapsed{transform:translateX(310px);opacity:0;pointer-events:none}.quest-top{display:flex;align-items:center;gap:8px}.quest-icon{width:28px;height:28px;background:rgba(238,178,88,.16);display:grid;place-items:center;border-radius:8px}.quest-top .eyebrow{flex:1;font-size:8px}.quest-top button{border:0;background:none;color:#dac6a8;font-size:19px;padding:0 2px}.quest-card h2{font-family:'Rye',serif;font-size:20px;font-weight:400;margin:12px 0 5px}.quest-card>p{font-size:10px;line-height:1.5;color:#d1bda3;margin:0 0 13px}.quest-progress,.quest-footer{display:flex;align-items:center;justify-content:space-between}.quest-progress{font-size:8px;letter-spacing:1.1px;color:#d7c3a9;font-weight:700;margin-bottom:6px}.quest-progress>span:last-child{font-size:11px;color:#ffdc94}.quest-progress i{font-style:normal;color:#c5b194;font-size:9px}.quest-line{height:4px}.quest-line i{width:0;background:linear-gradient(90deg,#d08040,#ffce76)}.quest-footer{font-size:10px;color:#e4c9a1;margin:11px 0 13px}.reward{color:#ffd47f;font-weight:700}.primary-button{height:37px;width:100%;display:flex;align-items:center;justify-content:space-between;padding:0 12px;border:0;border-radius:8px;background:linear-gradient(110deg,#b65c32,#d78242);box-shadow:0 5px 15px rgba(109,44,18,.24);font-size:9px;font-weight:800;letter-spacing:1px}.primary-button b{font-size:17px;font-weight:400}.primary-button:hover{filter:brightness(1.12);transform:translateY(-1px)}
.world-label{position:absolute;left:50%;transform:translateX(-50%);bottom:151px;padding:8px 14px;border:1px solid rgba(255,242,216,.27);border-radius:20px;background:rgba(40,29,20,.48);backdrop-filter:blur(8px);display:flex;gap:9px;align-items:center;font-size:8px;letter-spacing:1.3px;font-weight:700;color:#fff0d3;white-space:nowrap}.world-label i{font-style:normal;color:#eab45b}.world-label>span:last-child{color:#f3c274}.compass{border:1px solid rgba(255,229,180,.55);width:15px;height:15px;display:grid;place-items:center;border-radius:50%;font-size:7px;color:#ffd37a}.bottom-dock{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);width:min(780px,calc(100% - 44px));height:106px;border-radius:15px;display:flex;align-items:center;padding:12px 17px;gap:16px}.care-block,.ride-block{height:100%;display:flex;align-items:center;gap:9px}.care-block{flex:1.25}.ride-block{flex:1.35}.dock-title{min-width:102px}.dock-title span,.dock-title small{display:block}.dock-title span{font-size:9px;letter-spacing:1.1px;font-weight:800;color:#f5d69f}.dock-title small{font-size:7px;color:#b8a58d;letter-spacing:.6px;margin-top:4px}.care-action,.ride-action{height:57px;border:1px solid rgba(255,239,212,.13);background:rgba(255,255,255,.045);border-radius:10px;display:flex;align-items:center;gap:8px;text-align:left;padding:7px 9px;transition:.18s}.care-action:hover,.ride-action:hover{border-color:rgba(255,202,119,.58);background:rgba(255,196,105,.1);transform:translateY(-2px)}.care-action{min-width:74px}.care-action>span:nth-child(2) b,.care-action>span:nth-child(2) small,.ride-action>span:nth-child(2) b,.ride-action>span:nth-child(2) small{display:block;white-space:nowrap}.care-action b,.ride-action b{font-size:10px}.care-action small,.ride-action small{font-size:8px;color:#c7b49b;margin-top:3px}.action-icon{width:24px;height:24px;border-radius:7px;display:grid;place-items:center;font-size:16px;background:rgba(206,139,73,.2);color:#f4c477}.action-icon.feed{color:#b6d38e;background:rgba(131,171,97,.18)}.action-icon.pet{color:#e3a8b7;background:rgba(209,126,150,.17)}.dock-divider{height:55px;width:1px;background:var(--line)}.ride-action{flex:1;min-width:122px}.saddle-icon{width:28px;height:28px;border-radius:8px;background:rgba(223,160,79,.2);color:#ffd27f;display:grid;place-items:center;font-size:19px}.ride-action .keycap{font-size:8px;border:1px solid rgba(255,255,255,.2);border-radius:4px;padding:3px 5px;color:#dfcba9;margin-left:auto}.ride-hint{white-space:nowrap;font-size:8px;color:#bead97}.ride-hint kbd{font-family:inherit;color:#f4dfba;border:1px solid rgba(255,241,211,.28);border-radius:3px;padding:2px 3px;font-size:8px;margin-right:1px}.coins{display:flex;flex-direction:column;align-items:center;border-left:1px solid var(--line);padding-left:14px;min-width:48px}.coin{color:#f8c85e;font-size:17px}.coins b{font-size:13px;margin-top:1px}.coins small{font-size:7px;letter-spacing:.8px;color:#bca98e;margin-top:2px}.toast{position:absolute;top:47%;left:50%;transform:translate(-50%,10px);opacity:0;pointer-events:none;padding:11px 16px;border:1px solid rgba(255,231,184,.3);border-radius:10px;background:rgba(40,29,20,.86);color:#ffe0a2;font-size:12px;font-weight:700;box-shadow:0 8px 20px #301b1066;transition:.25s;z-index:5;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.help-modal{position:absolute;inset:0;background:rgba(25,18,14,.62);display:grid;place-items:center;opacity:0;pointer-events:none;transition:opacity .2s;z-index:10;padding:18px}.help-modal.open{opacity:1;pointer-events:auto}.help-box{width:min(460px,100%);padding:26px;border-radius:18px;position:relative}.modal-close{position:absolute;right:15px;top:12px;border:0;background:none;font-size:24px;color:#e8d5ba}.help-box h2{font-family:'Rye',serif;font-weight:400;font-size:23px;margin:9px 0 18px}.help-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px}.help-grid b{font-size:12px;color:#f5ce87}.help-grid p{font-size:10px;color:#cfbda4;line-height:1.55;margin:5px 0 0}.mobile-pad{display:none}
@media(max-width:850px){.topbar{padding:0 20px}.left-panel{left:18px;width:246px;padding:16px}.quest-card{right:18px;width:245px}.bottom-dock{gap:10px;padding:10px}.dock-title{min-width:85px}.care-block,.ride-block{gap:6px}.care-action{min-width:63px;padding:6px}.care-action>span:nth-child(2) small{display:none}.ride-hint{display:none}.world-label{bottom:141px}}
@media(max-width:620px){.topbar{height:64px;padding:0 14px}.brand{font-size:14px;gap:8px}.brand-mark{width:33px;height:33px}.brand small{font-size:7px}.weather{display:none}.top-right{gap:8px}.left-panel{top:75px;left:10px;width:190px;padding:12px;border-radius:13px}.eyebrow{font-size:7px}.horse-heading{margin-top:8px}.horse-heading h1{font-size:21px}.horse-heading p{font-size:7px}.level-badge{font-size:7px;padding:5px}.horse-art{height:72px;margin:8px -3px}.horse-emoji{font-size:54px}.horse-caption{font-size:6px}.stat-list{gap:8px}.stat-row{gap:6px}.stat-info>div:first-child{font-size:9px;margin-bottom:4px}.meter{height:4px}.horse-switch{margin-top:9px;padding-top:7px}.quest-card{top:auto;bottom:137px;right:10px;width:190px;padding:11px;border-radius:12px}.quest-icon{width:22px;height:22px;font-size:12px}.quest-top{gap:6px}.quest-top .eyebrow{font-size:6px}.quest-card h2{font-size:15px;margin:8px 0 4px}.quest-card>p{font-size:8px;margin-bottom:8px}.quest-progress{font-size:6px}.quest-footer{margin:8px 0;font-size:8px}.primary-button{height:31px;font-size:8px}.bottom-dock{bottom:8px;width:calc(100% - 16px);height:83px;padding:8px;gap:6px;border-radius:12px}.dock-title{display:none}.care-block,.ride-block{gap:4px}.care-block{flex:1.25}.ride-block{flex:1}.care-action{min-width:0;flex:1;height:52px;padding:5px 6px;flex-direction:column;justify-content:center;gap:2px;text-align:center}.care-action>span:nth-child(2) b{font-size:8px}.action-icon{width:22px;height:22px;font-size:14px}.dock-divider{height:46px}.ride-action{height:52px;min-width:0;padding:5px;gap:5px}.ride-action .saddle-icon{width:22px;height:22px;font-size:15px}.ride-action .keycap,.ride-action small{display:none}.ride-action b{font-size:8px}.coins{padding-left:6px;min-width:34px}.coins b{font-size:10px}.coins small{font-size:6px}.coin{font-size:13px}.world-label{bottom:102px;font-size:7px;padding:6px 10px}.mobile-pad{position:absolute;display:grid;grid-template-columns:39px 39px 39px;grid-template-rows:39px 39px;gap:4px;left:10px;bottom:108px;z-index:2;opacity:.85}.mobile-pad button{border:1px solid rgba(255,241,210,.48);background:rgba(44,31,20,.55);backdrop-filter:blur(7px);border-radius:11px;font-size:13px;color:#ffe0a6;touch-action:none}.mobile-pad button:nth-child(1){grid-column:1;grid-row:2}.mobile-pad .up{grid-column:2;grid-row:1}.mobile-pad button:nth-child(3){grid-column:2;grid-row:2}.mobile-pad button:nth-child(4){grid-column:3;grid-row:2}.help-grid{gap:10px}.help-box{padding:21px}.help-box h2{font-size:19px}.help-grid p{font-size:9px}}
@media(max-height:650px) and (min-width:621px){.left-panel{top:91px;padding:12px;width:230px}.horse-art{height:75px;margin:6px -3px}.quest-card{top:91px;padding:13px}.bottom-dock{height:88px;bottom:10px}.world-label{bottom:112px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $ = (s) => document.querySelector(s);
const scene = new THREE.Scene();
const renderer = new THREE.WebGLRenderer({canvas:$('#world'),antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true;
renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.outputColorSpace=THREE.SRGBColorSpace;
renderer.toneMapping=THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure=1.12;
const camera = new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,700);
scene.fog = new THREE.Fog(0xd99a68,95,330);

const horses = [
  {name:'Cinder',breed:'MUSTANG',years:4,color:0x68402f,mane:0x30231e,emoji:'🐎',speed:1.04,stamina:100},
  {name:'Sundance',breed:'PAINT HORSE',years:5,color:0xe9dcc1,mane:0x482b20,emoji:'🐴',speed:.96,stamina:115},
  {name:'Copper',breed:'QUARTER HORSE',years:3,color:0xa65d2e,mane:0x3c241b,emoji:'🐎',speed:1.16,stamina:92}
];
let horseIndex=0, bond=72, spirit=84, stamina=100, coins=240, level=1;
let mode='stable', raceActive=false, raceElapsed=0, nextGate=0, toastTimer=0;
const keys={};
let audioCtx=null,musicOn=false,musicTimer=null;
let worldTime=0;
const horseRoot=new THREE.Group();
scene.add(horseRoot);
let horseRig=null;
const gates=[];
const props=[];

function mat(color,roughness=.9,extra={}){return new THREE.MeshStandardMaterial({color,roughness,...extra});}
function box(parent,w,h,d,material,x=0,y=0,z=0){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function ball(parent,x,y,z,sx,sy,sz,material){const m=new THREE.Mesh(new THREE.SphereGeometry(1,16,12),material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function cylinder(parent,r1,r2,h,material,x,y,z,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}

function initWorld(){
  scene.background=new THREE.Color(0xd99462);
  const hemi=new THREE.HemisphereLight(0xffe6c6,0x806044,2.1);scene.add(hemi);
  const sun=new THREE.DirectionalLight(0xffd49a,3.2);sun.position.set(-45,70,30);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-100;sun.shadow.camera.right=100;sun.shadow.camera.top=100;sun.shadow.camera.bottom=-100;sun.shadow.bias=-.0002;scene.add(sun);
  const ground=new THREE.Mesh(new THREE.PlaneGeometry(700,700),mat(0xc58a56));ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
  // Rolling sandy ridges and distant red-rock country.
  for(let i=0;i<16;i++){const x=(i%8)*57-195,z=Math.floor(i/8)*-180-80;const hill=new THREE.Mesh(new THREE.SphereGeometry(1,24,16),mat(i%2?0xc78652:0xb9784a));hill.position.set(x,-8,z);hill.scale.set(48,17,40);scene.add(hill);}
  for(let i=0;i<11;i++){const x=(i-5)*54-10,z=-205-Math.sin(i*1.6)*26;const rock=new THREE.Mesh(new THREE.CylinderGeometry(11+Math.random()*8,20+Math.random()*14,42+Math.random()*28,5),mat(i%2?0xa35e45:0xb86c4d));rock.position.set(x,18,z);rock.rotation.y=Math.random();scene.add(rock);}
  // sun disk
  const sunDisk=new THREE.Mesh(new THREE.SphereGeometry(8,24,16),new THREE.MeshBasicMaterial({color:0xffe6a3}));sunDisk.position.set(-92,47,-235);scene.add(sunDisk);
  // Distant ranch buildings.
  buildRanch();
  // Scattered cacti, scrub, boulders and tumbleweed.
  for(let i=0;i<55;i++){let x=(Math.random()-.5)*270,z=(Math.random()-.5)*250;if(Math.abs(x)<12&&Math.abs(z)<35)continue;buildCactus(x,z, .7+Math.random()*.8);}
  for(let i=0;i<95;i++){let x=(Math.random()-.5)*240,z=(Math.random()-.5)*210;if(Math.abs(x)<10&&Math.abs(z)<24)continue;buildShrub(x,z);}
  createCourse();
  createHorse();
  horseRoot.position.set(0,0,8);
}
function buildRanch(){
  const wood=mat(0x71412c),woodLight=mat(0x98603c),roof=mat(0x50342b),cream=mat(0xe4c18c);
  const barn=new THREE.Group();barn.position.set(-19,0,-12);scene.add(barn);
  box(barn,15,7,10,wood,0,3.5,0);const roofMesh=new THREE.Mesh(new THREE.ConeGeometry(10.3,4,4),roof);roofMesh.rotation.y=Math.PI/4;roofMesh.scale.set(1,1,.75);roofMesh.position.set(0,9,0);roofMesh.castShadow=true;barn.add(roofMesh);
  box(barn,4.5,4.2,.25,roof,0,2.1,5.08);box(barn,1.3,2.8,.3,woodLight,0,1.4,5.25);box(barn,.08,2.7,.35,cream,0,1.4,5.45);box(barn,3.1,.2,.3,cream,0,3,5.4);
  const sign=box(barn,5.5,1.15,.22,roof,0,6.1,5.1);sign.rotation.z=0; // stable sign
  for(let x=-7;x<=7;x+=14)for(let z=-4;z<=4;z+=8)box(barn,.38,8,.38,woodLight,x,4,z);
  // Corral fence.
  const fence=mat(0xb27b4f);for(let z=8;z<=25;z+=4){for(const x of [-10,-3,4]){box(scene,.22,1.1,.22,fence,x,.55,z);box(scene,3.4,.15,.18,fence,x+1.6,.72,z);box(scene,3.4,.15,.18,fence,x+1.6,.34,z);}}
  for(let x=-10;x<=4;x+=3.5){box(scene,.22,1.1,.22,fence,x,.55,8);box(scene,.22,1.1,.22,fence,x,.55,25);}
}
function buildCactus(x,z,s){
  const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(s);scene.add(g);const green=mat(0x47724b),dark=mat(0x33583c);
  cylinder(g,.44,.55,3.5,green,0,1.75,0,9);ball(g,0,3.5,0,.43,.45,.43,green);
  if(Math.random()>.25){cylinder(g,.2,.24,1.15,green,.72,1.7,0,8);cylinder(g,.2,.2,1.1,green,.93,2.25,0,8);ball(g,.2,2.83,0,.2,.2,.2,green);}
  if(Math.random()>.48){cylinder(g,.18,.2,1.1,dark,-.66,1.15,0,8);cylinder(g,.18,.18,.9,dark,-.86,1.6,0,8);ball(g,-.86,2.05,0,.18,.18,.18,dark);}
}
function buildShrub(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const c=Math.random()>.5?0x9c5e3a:0x746344;for(let i=0;i<4;i++){const b=ball(g,(Math.random()-.5)*.8,.25+Math.random()*.25,(Math.random()-.5)*.7,.55,.3,.45,mat(c));b.rotation.y=Math.random();}if(Math.random()<.14){const rock=ball(g,0,.15,0,.6,.35,.55,mat(0x9f7658));}}

